def run_length(s: str) -> str:
    """Run-length encode s: each run of a repeated character becomes the character followed by the run's length.

    >>> run_length('aaabcc')
    'a3b1c2'
    """
    if not s:
        return ""

    result = []
    count = 1
    prev = s[0]

    for char in s[1:]:
        if char == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = char
            count = 1

    # append the last run
    result.append(f"{prev}{count}")
    return "".join(result)

