    """xs is sorted ascending with distinct values. Return the index of x in xs, or -1 if it is absent.

    >>> binary_search([1, 3, 5, 7, 9], 7)
    3
    """
    low, high = 0, len(xs) - 1
    while low <= high:
        mid = (low + high) // 2
        mid_val = xs[mid]
        if mid_val == x:
            return mid
        elif mid_val < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

