def word_counts(text: str) -> dict[str, int]:
    """Count the words of text, case-insensitively. Words are separated by whitespace; the characters .,!? around them are not part of the word.

    >>> word_counts('The cat and the hat.')
    {'the': 2, 'cat': 1, 'and': 1, 'hat': 1}
    """
    counts: dict[str, int] = {}
    for token in text.split():
        # Remove leading/trailing punctuation
        word = token.strip('.,!?').lower()
        if word:  # skip empty strings that may result from only punctuation
            counts[word] = counts.get(word, 0) + 1
    return counts

def word_counts(text: str) -> dict[str, int]:
    """Count the words of text, case‑insensitively. Words are separated by whitespace; the characters .,!? around them are not part of the word.

    >>> word_counts('The cat and the hat.')
    {'the': 2, 'cat': 1, 'and': 1, 'hat': 1}
    """
    from collections import Counter

    # split on whitespace
    tokens = text.split()
    cleaned = [token.strip('.,!?').lower() for token in tokens if token.strip('.,!?')]
    return dict(Counter(cleaned))

