    """Return True if every bracket in s, of the kinds (), [] and {}, is closed in the right order. Other characters are ignored.

    >>> balanced('([]{})')
    True
    """
    pairs = {'(': ')', '[': ']', '{': '}'}
    opens = set(pairs.keys())
    closes = set(pairs.values())
    stack = []

    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in closes:
            if not stack:
                return False
            if pairs[stack.pop()] != ch:
                return False

    return not stack

