def rotate(xs: list, k: int) -> list:
    """Return xs rotated right by k positions. k may be larger than len(xs) or negative; an empty list stays empty.

    >>> rotate([1, 2, 3, 4, 5], 2)
    [4, 5, 1, 2, 3]
    """
    n = len(xs)
    if n == 0:
        return xs
    # Normalize k to be within the bounds of the list length
    k = k % n
    if k == 0:
        return xs.copy()
    return xs[-k:] + xs[:-k]

def to_binary(n: int) -> str:
    """Return the binary digits of the non-negative integer n without a prefix; 0 is '0'.

    >>> to_binary(0)
    '0'
    """
    if n == 0:
        return '0'
    if n < 0:
        raise ValueError("n must be non-negative")
    return bin(n)[2:]

